# Original transparent transport wrapper for an already reviewed job.
# Reconstructs exact reviewed bytes; does not fetch or execute unverified input.
import ast,base64,gzip,json,hashlib,sys,os
from pathlib import Path
PAYLOAD = ''
p=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
old=Path('/output/cloud_job_v2.py').read_bytes()
assert hashlib.sha256(old).hexdigest()==p['oldBootstrapSHA256']
values={}
for node in ast.parse(old).body:
 if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name) and node.targets[0].id in ['SOURCE_B64','WHEELS']:
  values[node.targets[0].id]=ast.literal_eval(node.value)
a=base64.b64decode(values['SOURCE_B64'])
assert hashlib.sha256(a).hexdigest()==p['oldSourceSHA256']
b=b''.join(a[op[1]:op[2]] if op[0]=='copy' else base64.b64decode(op[1]) for op in p['ops'])
assert hashlib.sha256(b).hexdigest()==p['newSourceSHA256']
code=p['template'].replace("'SOURCE_ARCHIVE_BASE64'",repr(base64.b64encode(b).decode())).replace("'SOURCE_ARCHIVE_SHA256'",repr(p['newSourceSHA256'])).replace('[] # PINNED_WHEELS',repr(values['WHEELS'])).replace("'JOB_REVISION'",repr('v3'))
assert hashlib.sha256(code.encode()).hexdigest()==p['newBootstrapSHA256']
out=Path('/tmp/cloud_job_v3.py')
with out.open('x') as f:f.write(code)
print('TRANSPORT reconstructed exact reviewed input '+p['newBootstrapSHA256'],flush=True)
os.execv(sys.executable,[sys.executable,'-I',str(out)])
